"""Recursos do Ticker Battle recortados da cartela oficial (WebP em base64; cada peça preparada individualmente)."""
_A = {
 "raposa_confiante": "",
 "raposa_animada": "",
 "raposa_surpresa": "",
 "raposa_vitoriosa": "",
 "raposa_derrotada": "",
 "raposa_pensativa": "",
 "faixa_vitoria": "",
 "faixa_derrota": "",
 "faixa_empate": "",
 "faixa_decisiva": "",
 "faixa_prepare": "",
 "rodada_1": "",
 "rodada_2": "",
 "rodada_3": "",
 "ic_online": "",
 "ic_historico": "",
 "ic_cpu": "",
 "ic_aviso": "",
}


def uri(nome: str) -> str:
    return "data:image/webp;base64," + _A[nome]


def img(nome: str, h: int = 0, w: int = 0, cls: str = "", alt: str = "") -> str:
    t = (f' height="{h}"' if h else "") + (f' width="{w}"' if w else "") + (f' class="{cls}"' if cls else "")
    return f"<img src='{uri(nome)}' alt='{alt}'{t}>"
